// Reconstruct what each panel actually painted, in archive order, and flag a
// sequence that moves backwards on that panel. Only an event P is a paint; an
// event S is a transport delivery that the panel suppressed and never displayed.
const terminalByPanel = new Map();
for (const row of terminal) {
  if (!terminalByPanel.has(row.panel)) terminalByPanel.set(row.panel, []);
  terminalByPanel.get(row.panel).push(row);
}

const panelTraces = [];
const inversions = [];
for (const [panel, rows] of terminalByPanel.entries()) {
  rows.sort((left, right) => secondsOfDay(left.utc) - secondsOfDay(right.utc));
  const paints = rows.filter((row) => row.event === "P");
  const suppressed = rows.filter((row) => row.event === "S");
  let highest = -Infinity;
  let previous = null;
  for (const row of paints) {
    const sequence = Number(row.sequence);
    if (sequence < highest) {
      inversions.push({
        panel,
        site: panelName(panel),
        stationType: panelClass(panel),
        utc: row.utc,
        request: row.req,
        sequence,
        previousPaint: previous === null ? null : { utc: previous.utc, request: previous.req, sequence: Number(previous.sequence) },
        highestSequenceBefore: highest,
      });
    }
    highest = Math.max(highest, sequence);
    previous = row;
  }
  panelTraces.push({
    panel,
    site: panelName(panel),
    stationType: panelClass(panel),
    paints: paints.map((row) => ({
      utc: row.utc,
      feed: row.feed,
      sequence: Number(row.sequence),
      request: row.req,
      event: row.event,
    })),
    suppressed: suppressed.map((row) => ({
      utc: row.utc,
      feed: row.feed,
      sequence: Number(row.sequence),
      request: row.req,
      event: row.event,
    })),
  });
}

const liveInversions = inversions.filter((row) => row.stationType === "live");
const trainingInversions = inversions.filter((row) => row.stationType === "training");
const suppressedStaleRetries = [];
for (const stale of staleRetries) {
  for (const row of terminal) {
    if (
      row.event === "S" &&
      row.req === stale.request &&
      Number(row.sequence) === stale.replayedSequence &&
      secondsOfDay(row.utc) >= secondsOfDay(stale.retryUtc) &&
      panelClass(row.panel) === "live"
    ) {
      suppressedStaleRetries.push({
        panel: row.panel,
        site: panelName(row.panel),
        utc: row.utc,
        request: row.req,
        sequence: Number(row.sequence),
        suppressedAfterRetry: stale.retryUtc,
      });
    }
  }
}

